<?php
declare(strict_types=1);
require_once __DIR__ . '/api/core/App.php';
$root=require_role('superadministrador');
$users=db()->query('SELECT u.id_usuario,u.nombres,u.apellidos,u.usuario,u.correo,u.estado,r.nombre AS role FROM usuarios u JOIN roles r ON r.id_rol=u.id_rol ORDER BY u.id_usuario')->fetchAll();
$createState=take_form_state('user_create');
$createValues=is_array($createState['values']??null)?$createState['values']:[];
$createErrors=is_array($createState['errors']??null)?$createState['errors']:[];
$createValue=static fn(string $key,string $default=''):string=>h((string)($createValues[$key]??$default));
$createStatus=static fn(string $key):string=>isset($createErrors[$key])?' class="is-invalid" aria-invalid="true" aria-describedby="create-error-'.h($key).'"':'';
$createError=static fn(string $key):string=>'<small class="field-error" id="create-error-'.h($key).'" data-field-error="'.h($key).'">'.h((string)($createErrors[$key]??'')).'</small>';
page_start('Gestión de roles');
echo '<section class="page-heading"><div><span class="eyebrow">SUPERADMINISTRACIÓN</span><h1>Perfiles de usuario</h1><p>Solo superadministración puede cambiar perfiles. Administra cuentas básicas, estudiantes, empresas y coordinación desde esta pantalla.</p></div></section>';
$roleLabels=['usuario'=>'Usuario','estudiante'=>'Estudiante','empresa'=>'Empresa','administrador'=>'Administrador','superadministrador'=>'Superadministrador'];
echo '<section class="panel"><div class="panel-heading"><div><span class="eyebrow">ALTA DE CUENTAS</span><h2>Crear usuario</h2><p>La cuenta y su perfil se crearán automáticamente según el tipo que elijas.</p></div></div>'.(!empty($createState['message'])?'<div class="notice notice-error" role="alert">'.h((string)$createState['message']).'</div>':'').'<form method="post" action="'.h(app_url('api/usuarios.php')).'" data-validation-form="user-create">'.csrf_field().'<input type="hidden" name="accion" value="crear_usuario"><div class="form-grid"><label>Nombres *<input name="nombres" maxlength="100" pattern="[A-Za-zÁÉÍÓÚÜÑáéíóúüñ .-]+" required'.$createStatus('nombres').' value="'.$createValue('nombres').'">'.$createError('nombres').'</label><label>Apellidos *<input name="apellidos" maxlength="100" pattern="[A-Za-zÁÉÍÓÚÜÑáéíóúüñ .-]+" required'.$createStatus('apellidos').' value="'.$createValue('apellidos').'">'.$createError('apellidos').'</label><label>Usuario para iniciar sesión *<input name="usuario" minlength="3" maxlength="40" pattern="[A-Za-z0-9._-]+" autocomplete="username" required'.$createStatus('usuario').' value="'.$createValue('usuario').'">'.$createError('usuario').'</label><label>Correo *<input type="email" name="correo" maxlength="254" required'.$createStatus('correo').' value="'.$createValue('correo').'">'.$createError('correo').'</label><label>Teléfono<input name="telefono" maxlength="25" pattern="[+0-9() .-]{7,25}" title="Usa de 7 a 25 caracteres numéricos o separadores."'.$createStatus('telefono').' value="'.$createValue('telefono').'">'.$createError('telefono').'</label><label>Contraseña temporal *<input type="password" name="password" minlength="10" maxlength="200" autocomplete="new-password" required'.$createStatus('password').'><small>Mínimo 10 caracteres.</small>'.$createError('password').'</label><label>Tipo de cuenta *<select name="rol" required'.$createStatus('rol').'><option value="estudiante"'.($createValue('rol','estudiante')==='estudiante'?' selected':'').'>Estudiante</option><option value="empresa"'.($createValue('rol')==='empresa'?' selected':'').'>Empresa</option><option value="administrador"'.($createValue('rol')==='administrador'?' selected':'').'>Administrador</option></select>'.$createError('rol').'</label></div><p class="muted">Los datos académicos o empresariales iniciales se completan automáticamente y pueden actualizarse después.</p><button class="button button-primary" type="submit">Crear usuario</button></form></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">CUENTAS EXISTENTES</span><h2>Gestionar perfiles</h2><p>Los cambios de perfil también están restringidos a superadministración.</p></div></div><div class="table-wrap"><table><thead><tr><th>Usuario</th><th>Perfil actual</th><th>Asignar perfil</th></tr></thead><tbody>';
foreach($users as $u){$isSelf=(int)$u['id_usuario']===(int)$root['id'];echo '<tr><td>'.h($u['nombres'].' '.$u['apellidos']).'<small>'.h($u['correo']).'</small></td><td>'.h($roleLabels[$u['role']]??$u['role']).' · '.h($u['estado']).'</td><td><form method="post" action="'.h(app_url('api/usuarios.php')).'" data-role-form>'.csrf_field().'<input type="hidden" name="id_usuario" value="'.h($u['id_usuario']).'"><label class="sr-only" for="role-'.h($u['id_usuario']).'">Perfil para '.h($u['nombres'].' '.$u['apellidos']).'</label><select id="role-'.h($u['id_usuario']).'" name="rol" required'.($isSelf?' disabled':'').'>';foreach($roleLabels as $value=>$label)echo '<option value="'.h($value).'"'.($u['role']===$value?' selected':'').'>'.h($label).'</option>';echo '</select><details class="role-profile-fields"><summary>Datos de perfil si aún no existe</summary><div class="form-grid"><label>Carné<input name="carnet" maxlength="40" autocomplete="off"></label><label>Carrera<input name="carrera" maxlength="150"></label><label>Universidad<input name="universidad" maxlength="180"></label><label>Nombre legal de empresa<input name="nombre_legal" maxlength="180"></label><label>Correo de contacto<input name="correo_contacto" type="email" maxlength="254"></label></div><small>Se solicitan solo al asignar estudiante o empresa a una cuenta sin ese perfil.</small></details>'.($isSelf?'<small>No puedes cambiar tu propio perfil.</small>':'<button class="button button-small button-primary" type="submit">Guardar perfil</button>').'</form></td></tr>';}
echo '</tbody></table></div></section>';page_end();
